-- Publicaciones verificadas en los perfiles oficiales. Conserva el histórico.
begin;
update public.social_posts set web_order=100+web_order where show_on_web=true and web_order<100;
insert into public.social_posts(platform,external_id,url,title,caption,thumbnail_url,web_order,post_type,published_at,disponible,show_on_web,thumbnail_is_ephemeral,last_scraped_at,updated_at)
select platform,external_id,url,title,caption,thumbnail_url,web_order,post_type,published_at,disponible,show_on_web,thumbnail_is_ephemeral,now(),now()
from jsonb_to_recordset('[{"platform":"instagram","external_id":"DfNZrRnJLmg","url":"https://www.instagram.com/banda_bruna/reel/DfNZrRnJLmg/","title":"Banda Bruna en todas las plataformas digitales","caption":"Esto y mucho más en todas las plataformas digitales!!\n\n.\n.\n.\n.\n.\n.\n.\n.\n#cumbia #chile #viral #parati #bandabruna","thumbnail_url":"/assets/images/social/instagram-DfNZrRnJLmg.webp","web_order":1,"post_type":"reel","published_at":"2026-11-01T18:44:56Z","disponible":true,"show_on_web":true,"thumbnail_is_ephemeral":false},{"platform":"facebook","external_id":"1091912600414432","url":"https://www.facebook.com/reel/1091912600414432/","title":"Banda Bruna en La Brújula Sonora","caption":"Un recuerdo de nuestra participación en la Brujula Sonara con la conducción de Francys Suazo Egaña!","thumbnail_url":"/assets/images/social/facebook-1091912600414432.webp","web_order":2,"post_type":"reel","published_at":null,"disponible":true,"show_on_web":true,"thumbnail_is_ephemeral":false},{"platform":"tiktok","external_id":"7700406660996599048","url":"https://www.tiktok.com/@bandabrunaoficial/video/7700406660996599048","title":"Banda Bruna · Reel del 24 de octubre","caption":"Publicación oficial de Banda Bruna en TikTok.","thumbnail_url":"/assets/images/social/tiktok-7700406660996599048.webp","web_order":3,"post_type":"video","published_at":null,"disponible":true,"show_on_web":true,"thumbnail_is_ephemeral":false},{"platform":"youtube","external_id":"RzhLrh0pqc8","url":"https://www.youtube.com/watch?v=RzhLrh0pqc8","title":"Banda Bruna - Agonía (Acústico)","caption":"Video oficial de Banda Bruna en YouTube.","thumbnail_url":"https://i.ytimg.com/vi/RzhLrh0pqc8/hqdefault.jpg","web_order":4,"post_type":"video","published_at":null,"disponible":true,"show_on_web":true,"thumbnail_is_ephemeral":false},{"platform":"instagram","external_id":"DfI1e4YAejR","url":"https://www.instagram.com/muniteodoro/reel/DfI1e4YAejR/","title":"Banda Bruna en Teletón · Barros Arana","caption":"BANDA BRUNA EN TELETON BARROS ARANA","thumbnail_url":"/assets/images/social/instagram-DfI1e4YAejR.webp","web_order":5,"post_type":"reel","published_at":null,"disponible":true,"show_on_web":true,"thumbnail_is_ephemeral":false},{"platform":"youtube","external_id":"l4Mot_5dx-M","url":"https://www.youtube.com/shorts/l4Mot_5dx-M","title":"Tremendo show · SOFO Temuco","caption":"Video oficial de Banda Bruna en YouTube.","thumbnail_url":"https://i.ytimg.com/vi/l4Mot_5dx-M/hqdefault.jpg","web_order":6,"post_type":"short","published_at":null,"disponible":true,"show_on_web":true,"thumbnail_is_ephemeral":false},{"platform":"tiktok","external_id":"7698954345416592648","url":"https://www.tiktok.com/@bandabrunaoficial/video/7698954345416592648","title":"Banda Bruna · Reel del 21 de octubre","caption":"Publicación oficial de Banda Bruna en TikTok.","thumbnail_url":"/assets/images/social/tiktok-7698954345416592648.webp","web_order":7,"post_type":"video","published_at":null,"disponible":true,"show_on_web":true,"thumbnail_is_ephemeral":false},{"platform":"instagram","external_id":"De8DW1sJKCQ","url":"https://www.instagram.com/banda_bruna/reel/De8DW1sJKCQ/","title":"Tus besos son · Sesión en vivo","caption":"➡️ Tus besos son disponible en nuestra ultima sesión en vivo en nuestro canal de youtube\n\n➡️ la sesión ya tiene 16K de reproducciones !!\n\n➡️ Comparte con tus amigos para que podamos llegar a todo Chile en nuestros proximos conciertos !","thumbnail_url":"/assets/images/social/instagram-De8DW1sJKCQ.webp","web_order":8,"post_type":"reel","published_at":null,"disponible":true,"show_on_web":true,"thumbnail_is_ephemeral":false},{"platform":"youtube","external_id":"e_he1CiJWDs","url":"https://www.youtube.com/shorts/e_he1CiJWDs","title":"Campo Viejo · Villarrica","caption":"Video oficial de Banda Bruna en YouTube.","thumbnail_url":"https://i.ytimg.com/vi/e_he1CiJWDs/hqdefault.jpg","web_order":9,"post_type":"short","published_at":null,"disponible":true,"show_on_web":true,"thumbnail_is_ephemeral":false},{"platform":"tiktok","external_id":"7696725485157387521","url":"https://www.tiktok.com/@bandabrunaoficial/video/7696725485157387521","title":"Banda Bruna · Reel del 15 de octubre","caption":"Publicación oficial de Banda Bruna en TikTok.","thumbnail_url":"/assets/images/social/tiktok-7696725485157387521.webp","web_order":10,"post_type":"video","published_at":null,"disponible":true,"show_on_web":true,"thumbnail_is_ephemeral":false}]'::jsonb) as p(platform text,external_id text,url text,title text,caption text,thumbnail_url text,web_order integer,post_type text,published_at timestamptz,disponible boolean,show_on_web boolean,thumbnail_is_ephemeral boolean)
on conflict(platform,external_id) do update set url=excluded.url,title=excluded.title,caption=excluded.caption,thumbnail_url=excluded.thumbnail_url,web_order=excluded.web_order,post_type=excluded.post_type,published_at=coalesce(excluded.published_at,social_posts.published_at),disponible=true,show_on_web=true,thumbnail_is_ephemeral=false,last_scraped_at=now(),updated_at=now();
commit;
select platform,title,url,web_order from public.social_posts where show_on_web=true and disponible=true order by web_order limit 10;
